import { Context } from "effect";
import { HttpContext } from "../schema/errors.js";
export class RequestExecutorService extends Context.Service()("@opencode/AI/RequestExecutor") {
}
export const Service = RequestExecutorService;
/**
 * The client certificate for the HTTP request being executed. Transports set it from `http.tls`; the executor's HTTP
 * client presents it, since only the runtime's fetch can.
 */
export const CurrentTls = Context.Reference("@opencode/AI/RequestExecutor/CurrentTls", {
    defaultValue: () => undefined,
});
export const headerDetails = (headers) => Object.fromEntries(Object.entries(headers).map(([name, value]) => [name, value]));
export const responseHttp = (response) => new HttpContext({
    url: response.request.url,
    status: response.status,
    headers: headerDetails(response.headers),
});
